files.content:
* {
  box-sizing: border-box;
}

.page {
  height: 100vh;
  margin: 0;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.yo {
  --breakpoint-simulation: (100vw - var(--breakpoint));
  --breakpoint: 500px;

  /* Укажите переменную с вычислениями имитирующими брейкпоинт */
  position: fixed;
}
